function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 100) return 'mat needs 1 to 100 columns.';
  for (const row of mat) {
    if (row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer from 1 to 100.';
  }
  return null;
}

