function diagonalSort(mat) {
  const m = mat.length, n = mat[0].length;
  const out = mat.map(row => row.slice());
  const starts = [];
  for (let c = 0; c < n; c++) starts.push([0, c]);
  for (let r = 1; r < m; r++) starts.push([r, 0]);
  for (const [r0, c0] of starts) {
    const len = Math.min(m - r0, n - c0);
    // Bubble sort directly along the diagonal cells.
    for (let pass = 0; pass < len; pass++) {
      for (let k = 0; k + 1 < len - pass; k++) {
        const a = out[r0 + k][c0 + k], b = out[r0 + k + 1][c0 + k + 1];
        if (a > b) { out[r0 + k][c0 + k] = b; out[r0 + k + 1][c0 + k + 1] = a; }
      }
    }
  }
  return out;
}

