function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const m = large ? (rand() < 0.4 ? 100 : int(40, 100)) : int(1, 6);
  const n = large ? (rand() < 0.4 ? 100 : int(40, 100)) : int(1, 6);
  const top = large ? 100 : (rand() < 0.5 ? 4 : 100);
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => int(1, top)));
  return [mat];
}
